\usepackage{booktabs}

\title{Irrigation Access and Household Income in Semi-Arid Districts:
Evidence from a Three-District Household Survey}
\author{A.~Diallo, R.~Fernandes, and T.~Nguyen}
\date{June 2026}

\begin{document}
\maketitle

\begin{abstract}
We study how access to small-scale irrigation shapes cultivated area
and household income in three semi-arid districts, linking a household
survey to water-user association records over two agricultural seasons.
\end{abstract}

\section{Survey Design}
% The survey covered 412 households in three districts. (pre-cleaning tally, kept for audit)
The survey covered 412 households in three districts.
Sampling was stratified by district and by distance to the nearest
functioning borehole, with households drawn from association rosters
and replaced only after three unsuccessful visit attempts.
The questionnaire covered plot inventories, water sources, labour
allocation, and off-farm earnings for the reference seasons.

\section{Fieldwork}
Enumerators completed two visit waves, in February and in September,
and supervisors back-checked a random ten percent of interviews.
Global-positioning readings were taken at each dwelling to link
households to the association's canal maps.

\section{Outcomes}
The primary outcomes are cultivated area under irrigation, staple
crop revenue, and total household income per adult equivalent.
All monetary amounts are expressed in constant 2024 prices using
the national consumer price index.

\section{Next Steps}
A second survey round is planned for the coming dry season and will
revisit the same households with a shortened instrument.
\end{document}

